// Igual que con la tienda: firma HMAC-SHA256 del cuerpo exacto, antigüedad y contrato.
const crypto = require('crypto');
const entrada = $input.first();
const h = entrada.json.headers || {};
const errores = [];
const exigir = (ok, campo, error) => { if (!ok) errores.push({ campo, error }); };
let crudo = entrada.binary && entrada.binary.data
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : JSON.stringify(entrada.json.body || {});
const secreto = $env.KITSUNE_SECRETO_GESTION || '';
const marca = String(h['x-kitsune-timestamp'] || '');
const recibida = String(h['x-kitsune-firma'] || '').replace(/^sha256=/, '');
const esperada = crypto.createHmac('sha256', secreto).update(marca + '.' + crudo).digest('hex');
const firmaOk = secreto !== '' && recibida.length === esperada.length && crypto.timingSafeEqual(Buffer.from(recibida), Buffer.from(esperada));
exigir(firmaOk, 'X-Kitsune-Firma', 'Firma ausente o incorrecta.');
if (firmaOk) exigir(Math.abs(Date.now() / 1000 - Number(marca)) <= 600, 'X-Kitsune-Timestamp', 'Envío caducado.');
let c = null;
try { c = JSON.parse(crudo); } catch (e) { errores.push({ campo: 'cuerpo', error: 'No es JSON.' }); }
const d = (c && c.datos) || {};
const REF = /^KN-\d{4}-\d{6}$/;
const ESTADOS = ['creado', 'pagado_simulado', 'pendiente_preparacion', 'enviado', 'entregado', 'incidencia', 'cancelado'];
let ruta = null;
if (c) {
  exigir(Number.isInteger(c.sincronizacion_id), 'sincronizacion_id', 'Obligatorio.');
  if (c.tipo === 'pedido.estado_cambiado') {
    ruta = 'estado';
    exigir(REF.test(d.pedido_referencia || ''), 'datos.pedido_referencia', 'Formato KN-AAAA-NNNNNN.');
    exigir(ESTADOS.includes(d.estado_nuevo), 'datos.estado_nuevo', 'Estado no válido.');
    if (d.estado_nuevo === 'enviado') exigir(String(d.seguimiento || '').trim() !== '', 'datos.seguimiento', 'Obligatorio para «enviado».');
  } else if (c.tipo === 'propuesta.aprobada') {
    ruta = 'propuesta';
    exigir(Number.isInteger(d.propuesta_id), 'datos.propuesta_id', 'Obligatorio.');
    exigir(String(d.mensaje || '').trim() !== '' && String(d.mensaje).length <= 1000, 'datos.mensaje', 'Mensaje vacío o demasiado largo.');
    exigir(!d.telegram_chat_id || /^-?\d{1,20}$/.test(String(d.telegram_chat_id)), 'datos.telegram_chat_id', 'Chat no válido.');
    exigir(!!d.aprobada_por, 'datos.aprobada_por', 'Falta quién la aprobó: sin aprobación humana no se envía nada.');
  } else {
    errores.push({ campo: 'tipo', error: 'Tipo de cambio desconocido.' });
  }
}
return [{ json: { valido: errores.length === 0, errores, codigo_rechazo: firmaOk ? 422 : 401, ruta, tipo: c && c.tipo,
  sincronizacion_id: c && c.sincronizacion_id, entidad: c && c.entidad, datos: d } }];

// 200 → aplicado (o ya estaba: idempotente) · 404/409/422 → conflicto, una persona debe revisarlo
// red o 5xx → la tienda no está disponible: 502 y el back-office lo deja pendiente y reintenta.
const caso = $('Verificar firma (back-office)').first().json;
const r = $json || {};
const d = caso.datos;
let resultado = 'ok', codigo = 200, tipo_error = null, mensaje = '', cuerpo = {};
if (r.statusCode === undefined) {
  resultado = 'error'; codigo = 502; tipo_error = 'tienda_no_disponible'; mensaje = typeof r.error === 'string' ? r.error : JSON.stringify(r.error || r).slice(0, 300);
} else {
  const s = Number(r.statusCode);
  cuerpo = typeof r.body === 'string' ? (() => { try { return JSON.parse(r.body); } catch (e) { return { mensaje: r.body }; } })() : (r.body || {});
  if (s >= 200 && s < 300) { resultado = cuerpo.resultado === 'sin_cambios' ? 'duplicado' : 'ok'; mensaje = 'Tienda: ' + (cuerpo.resultado || 'ok') + ' (' + (cuerpo.estado || d.estado_nuevo) + ')'; }
  else if ([404, 409, 422].includes(s)) { resultado = 'error'; codigo = 409; tipo_error = 'conflicto_tienda'; mensaje = String(cuerpo.mensaje || ('HTTP ' + s)); }
  else { resultado = 'error'; codigo = 502; tipo_error = 'tienda_http_' + s; mensaje = String(cuerpo.mensaje || ('HTTP ' + s)); }
}
// Aviso al cliente por Telegram (mensaje fijo, no lo escribe la IA) solo si lo tiene vinculado.
const en = d.idioma === 'en';
const TEXTOS = {
  pendiente_preparacion: en ? 'we are preparing your order' : 'estamos preparando tu pedido',
  enviado: (en ? 'your order is on its way' : 'tu pedido ya está en camino') + (d.seguimiento ? ` (${d.transportista || ''} ${d.seguimiento})`.replace('( ', '(') : ''),
  entregado: en ? 'your order has been delivered' : 'tu pedido figura como entregado',
  cancelado: en ? 'your order has been cancelled' : 'tu pedido se ha cancelado',
};
const aviso = resultado === 'ok' && d.telegram_chat_id && TEXTOS[d.estado_nuevo]
  ? (en ? `Kitsune Notes · order ${d.pedido_referencia}: ${TEXTOS[d.estado_nuevo]}.` : `Kitsune Notes · pedido ${d.pedido_referencia}: ${TEXTOS[d.estado_nuevo]}.`)
  : null;
return [{ json: { ...caso, resultado, codigo, tipo_error, mensaje, aviso } }];

// Resultado de ejecutar la propuesta aprobada:
//   con Telegram vinculado → enviada (o error: 409 si Telegram la rechaza, 502 si no responde)
//   sin Telegram → «ejecutada en modo simulado»: queda registrada pero no se envía a nadie.
const caso = $('Verificar firma (back-office)').first().json;
const d = caso.datos;
if (!d.telegram_chat_id) {
  return [{ json: { ...caso, resultado: 'ok', codigo: 200, estado: 'ejecutada_simulada',
    detalle: 'El cliente no tiene Telegram vinculado: el mensaje queda registrado en modo simulado, sin enviarse.' } }];
}
const r = $json || {};
const s = Number(r.statusCode || 0);
const cuerpo = (r.body && typeof r.body === 'object') ? r.body : {};
if (s === 200 && cuerpo.ok) {
  return [{ json: { ...caso, resultado: 'ok', codigo: 200, estado: 'ejecutada', telegram_message_id: cuerpo.result && cuerpo.result.message_id,
    detalle: 'Mensaje enviado por Telegram (mensaje ' + (cuerpo.result && cuerpo.result.message_id) + ').' } }];
}
if (s >= 400 && s < 500) {
  return [{ json: { ...caso, resultado: 'error', codigo: 409, estado: 'fallo_ejecucion', tipo_error: 'telegram_rechazo',
    detalle: 'Telegram no acepta el mensaje: ' + (cuerpo.description || ('HTTP ' + s)) } }];
}
return [{ json: { ...caso, resultado: 'error', codigo: 502, estado: 'pendiente', tipo_error: 'telegram_no_disponible',
  detalle: 'Telegram no responde; el back-office lo reintentará.' } }];
